What is the output?
for i in range(3):
    print(i, end=' ')

What is the output?
for i in range(1, 6, 2):
    print(i, end=' ')

Find the error.
for i in range(5)
    print(i)

What is the output?
for i in range(5):
    if i == 3:
        break
    print(i, end=' ')

What is the output?
for i in range(5):
    if i == 2:
        continue
    print(i, end=' ')

What is the output?
for ch in "CAT":
    print(ch, end=' ')

What is the output?
for i in range(2):
    for j in range(2):
        print(i, j)

What is the output?
for i in range(3):
    print(i)
else:
    print("Done")
